// ==============================================================================
// Field: Glass Blocks
// Macro:  Test("Glass Blocks", "Ted", "", "")
// Source: pixel/field_dir.sky.h:61
// Author: Ted
// Warp kind: GoDXY  (Cartesian, 1 feedback channel(s))  Aspect=0
// ==============================================================================
FieldResult field_Glass_Blocks(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = flor( rnd( 3 ) + 2 );
    a[1] = sgn( rnd( 2 ) - 1 );
    a[2] = flor( rnd( 20 - pow(a[0],2) ) + 10 );
    a[3] = flor( a[2] / ( 2 * a[0] ) ) * a[0];
    a[4] = 1/a[3];

    // ---- per pixel: GoDXY(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (clip( a[1] * sgn( fmod((a[0] * (x + a[0])),2) - .5 ) * sgn( fmod((a[0] * ( y + a[0] )) ,2) - .5 ) ));
    double sourceX = ( x - ( 1 - d[0] ) * sgn( x ) * rnd( .05 ) -       d[0]   * ( wrap( x * a[2] ) - .5 ) * a[4]);
    double sourceY = ( y -       d[0]   * sgn( y ) * rnd( .05 ) - ( 1 - d[0] ) * ( wrap( y * a[2] ) - .5 ) * a[4]);
    return FieldResult{ 0, false, sourceX, sourceY };  // -> Field::setXY(sourceX, sourceY)
}

