// ==============================================================================
// Field: Polar Tiles
// Macro:  Test("Polar Tiles", "Ted", "", "")
// Source: pixel/field_dir.sky.h:144
// Author: Ted
// Warp kind: GoDRT  (polar, 1 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Polar_Tiles(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = flor( rnd( 10 ) ) + 3;
    a[1] = 0.1 / a[0];
    a[2] = sgn( rnd( 2 ) - 1 );
    a[3] = rnd( 3.5 ) + .5;
    a[4] = a[3] / 2;
    a[5] = ( rnd( 1 / 6 ) + 1 / 3 ) * PI;
    a[6] = cos( a[5] );
    a[7] = sin( a[5] );
    a[8] = 1/ ( 2 * PI );

    // ---- per pixel: GoDRT(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (theta * a[8]);
    double sourceR = (radius + a[1] * ( a[3] * wrap( a[0] * ( a[6] * radius + a[2] * a[7] * d[0] ) ) - a[4] ));
    double sourceT = (theta + a[1] * ( a[3] * wrap( a[0] * ( a[6] * d[0] - a[2] * a[7] * radius ) ) - a[4] ));
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

// ==============================================================================
// Field: Polygon
// Macro:  Test("Polygon", "Ted", "", "")
// Source: pixel/field_dir.sky.h:160
// Author: Ted
// Warp kind: GoD4XY  (Cartesian, 4 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Polygon(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = flor( rnd( 6 ) + 3 );
    a[1] = 2 * PI;
    a[2] = rnd( a[1] );
    a[3] = rnd( 40 ) + 20;
    a[4] = 1/a[1];
    a[5] = 1/a[0];

    // ---- per pixel: GoD4XY(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (a[1] * ( flor( a[0] * wrap( theta * a[4] ) ) + .5 ) * a[5]);
    d[1] = (cos( d[0] ));
    d[2] = (sin( d[0] ));
    d[3] = (.01 * cos ( a[3] * radius * cos( theta - d[0] ) ) - .0125);
    double sourceX = (x + d[1] * d[3]);
    double sourceY = (y + d[2] * d[3]);
    return FieldResult{ 1, false, sourceX, sourceY };  // -> Field::setXY(sourceX, sourceY)
}

// ==============================================================================
// Field: Spiral Shoals
// Macro:  Test("Spiral Shoals", "Ted", "", "")
// Source: pixel/field_dir.sky.h:178
// Author: Ted
// Warp kind: GoD3RT  (polar, 3 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Spiral_Shoals(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = flor( rnd( 6 ) ) + 5;

    // ---- per pixel: GoD3RT(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (theta + sin( 30 * radius ) * .02);
    d[1] = (clip( sin( (d[0] + radius)* a[0] ) )/10);
    d[2] = (rnd( d[1] ) - .5 * d[1]);
    double sourceR = (radius - .01 + d[2]);
    double sourceT = (d[0] + d[2]);
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

