// Author: Ted
// Note:   equiangular spiral
// Warp kind: GoDRT  (polar, 1 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Spiraling(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = tan(PI/2+sgn(rnd(1)-.5)*(rnd(.5)+.05));
    a[1] = rnd(.03)+.03;
    a[2] = 1/a[0];

    // ---- per pixel: GoDRT(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (log(radius)*a[0]);
    double sourceR = (exp((d[0]+a[1])*a[2]));
    double sourceT = (theta+a[1]*pos(sin(d[0]*6)));
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

// ==============================================================================
// Field: Split and Twist
// Macro:  Test("Split and Twist", "Ted", "", "")
