// Warp kind: GoRT  (polar, 0 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Split_and_Twist(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = rnd(200)+50;
    a[1] = sgn(rnd(2)-1)*.01;
    a[2] = sgn(rnd(2)-1)*.01;

    // ---- per pixel: GoRT(...) -- evaluated for every (x,y) on the grid ----
    double sourceR = (radius+a[1]);
    double sourceT = (theta+.1*2*PI*( fmod(dabs(theta*a[0]),5)  -2)+a[2]);
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

// ==============================================================================
// Field: Star Glass
// Macro:  Test("Star Glass", "Ted", "", "")
// Source: pixel/field_dir.sky.h:212
// Author: Ted
// Warp kind: GoD2RT  (polar, 2 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Star_Glass(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = .03;
    a[1] = .7;
    a[2] = trnc( rnd( 20 ) + 5 );
    a[3] = fmod(a[2],2) * PI / (2 * a[2]);
    a[4] = a[2] / PI;
    a[5] = a[0]/2;
    a[6] = 1/40;

    // ---- per pixel: GoD2RT(...) -- evaluated for every (x,y) on the grid ----
    d[0] = (trwv( ( theta - a[3] ) * a[4] ) * .2);
    d[1] = (sqwv( ( radius - a[1] + d[0] ) * 7.5 ));
    double sourceR = (radius + ( 1 - d[1] ) * ( radius - a[1] + d[0] ) * a[6] + d[1] * ( rnd( a[0] ) + d[0] - .4 ));
    double sourceT = (theta + d[1] * ( rnd( a[0] ) - a[5] ));
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

