// ==============================================================================
// Field: Turbulence
// Macro:  Test("Turbulence", "Ted", "", "")
// Source: pixel/field_dir.sky.h:240
// Author: Ted
// Warp kind: GoRT  (polar, 0 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Turbulence(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = flor( rnd( 15 ) ) + 6;
    a[1] = flor( rnd( 7 ) );
    a[2] = a[0] / PI;

    // ---- per pixel: GoRT(...) -- evaluated for every (x,y) on the grid ----
    double sourceR = (radius + ( .01 * ( saw( theta * a[2] + a[1] * radius ) ) - .0125 ));
    double sourceT = (theta  + ( .01 * ( saw(              a[0] * radius ) ) - .0125 ));
    return FieldResult{ 1, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

// ==============================================================================
// Field: Twisted Tiles
// Macro:  Test("Twisted Tiles", "Ted", "", "HAL_Waves_Of_Grain")
// Source: pixel/field_dir.sky.h:249
// Author: Ted
// Note:   HAL_Waves_Of_Grain
// Warp kind: GoXY  (Cartesian, 0 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_Twisted_Tiles(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = rnd( 5 ) + .5;
    a[1] = 0.1 / a[0];
    a[2] = sgn( rnd( 2 ) - 1 );
    a[3] = a[1] * ( rnd( 3.5 ) + .5 );
    a[4] = a[3] / 2;

    // ---- per pixel: GoXY(...) -- evaluated for every (x,y) on the grid ----
    double sourceX = (x + a[3] * wrap( a[0] * ( x + a[2] * y ) ) - a[4]);
    double sourceY = (y + a[3] * wrap( a[0] * ( y - a[2] * x ) ) - a[4]);
    return FieldResult{ 1, false, sourceX, sourceY };  // -> Field::setXY(sourceX, sourceY)
}

