// Source: pixel/field_dir.sky.h:419
// Author: Jan Benz  <webmaster(at)janbenz.de>
// Warp kind: GoRT  (polar, 0 feedback channel(s))  Aspect=0
// ==============================================================================
FieldResult field_JB2___Bubble_Tunnel(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    // (no a[] setup constants)

    // ---- per pixel: GoRT(...) -- evaluated for every (x,y) on the grid ----
    double sourceR = (radius - radius / 32 * clip( radius ));
    double sourceT = (theta +  radius  / 16 * rnd( sin( theta ) * 2 ));
    return FieldResult{ 0, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

