// Warp kind: GoXY  (Cartesian, 0 feedback channel(s))  Aspect=1
// ==============================================================================
FieldResult field_DT___Horizon(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = 1.03 + rnd(0.02);
    a[1] = rnd(2)-0.5;
    a[2] = 0.015 + (rnd(0.07) * rnd(1))*(1+a[1]);

    // ---- per pixel: GoXY(...) -- evaluated for every (x,y) on the grid ----
    double sourceX = (x * a[0]);
    double sourceY = (y + a[2] * (a[1] + y -1));
    return FieldResult{ 1, false, sourceX, sourceY };  // -> Field::setXY(sourceX, sourceY)
}

