// ==============================================================================
// Field: Dreamscape 3
// Macro:  Test("Dreamscape 3", "Demonseed", "", "Based on Sunburst - Many")
// Source: pixel/field_rt.sky.h:481
// Author: Demonseed
// Note:   Based on Sunburst - Many
// Warp kind: GoD2RT  (polar, 2 feedback channel(s))  Aspect=0
// ==============================================================================
FieldResult field_Dreamscape_3(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    a[0] = trnc(18 + rnd(5)) * PI;
    a[1] = 1000 + rnd(1000);
    a[2] = rnd(0.5)+rnd(0.5);
    a[3] = rnd(0.5)+rnd(0.5);
    a[4] = sgn(0.5 - rnd(1))*(6 + rnd(2));
    a[5] = 1000 + rnd(1000);
    a[6] = rnd(0.5)+rnd(0.5);
    a[7] = -rnd(0.5)-rnd(0.5);

    // ---- per pixel: GoD2RT(...) -- evaluated for every (x,y) on the grid ----
    d[0] = ((a[0]/(10+((sqr(x+a[2])+sqr(y+a[3])) *a[1]))));
    d[1] = ((a[4]/(10+((sqr(x+a[6])+sqr(y+a[7])) *a[5]))));
    double sourceR = (radius * ((1 + sin(a[0] * theta))*0.03 +0.92));
    double sourceT = (theta - (d[0]*(x+a[2]) + d[1]*(x+a[6])));
    return FieldResult{ 0, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

